__NUXT_JSONP__("/svet/stat/lesotho/jidlo", (function(a,b,c,d,e,f,g,h,i,j,k,l,m,n){return {data:[{tabsLoad:{tabWhatToSee:d,tabPrice:d,tabPeople:d,tabTrip:d,tabContact:d,tabHotel:d,tabNeighboring:g,tabVideos:e,tabArticles:e,tabWallSockets:g,tabChains:g,tabFauna:e,tabFlora:e,tabFoods:e,tabBrands:e},place:[{tld:".ls",name:"Lesotho",area:30355,population:2125268,slug:j,id_continent:f,information_chatgpt:"\u003Cp\u003ELesotho je malá země nacházející se v jižní Africe, obklopená Jihoafrickou republikou. Je to jediná africká země, která leží celá nad nadmořskou výškou 1000 metrů a proto se jí přezdívá \"Střecha Afriky\". Tento fakt spolu s nádhernou přírodou dělá z Lesotha skvělé místo k návštěvě a prozkoumání.\u003C\u002Fp\u003E\n\u003Cp\u003ENejvětší atrakcí pro turisty jsou horští koně, kteří jsou neodmyslitelnou součástí kultury a způsobu života místních obyvatel. Můžete si pronajmout koně a prozkoumat tak krásnou krajinu Lesotha, která je plná divoké zvěře, vodopádů a horských řek.\u003C\u002Fp\u003E\n\u003Cp\u003EKromě toho můžete navštívit historické památky jako jsou staré pevnosti, kostely a paláce, které jsou důkazem bohaté historie této země. Lesotho má také mnoho kulturních festivalů, během kterých si můžete užít místní hudbu, tance a tradiční jídlo.\u003C\u002Fp\u003E\n\u003Cp\u003ELesotho je také domovem národního parku Sehlabathebe, který je jedním z nejkrásnějších parků v zemi. Zde můžete pozorovat mnoho druhů zvířat v přirozeném prostředí, jako jsou například sloni, buvoli a gazely.\u003C\u002Fp\u003E\n\u003Cp\u003ENicméně, Lesotho je stále velmi chudou zemí a turisté by měli být připraveni na to, že infrastruktura zde může být nedostatečná a základní služby mohou být omezené. Je důležité být opatrný a dodržovat základní bezpečnostní opatření během cestování po zemi.\u003C\u002Fp\u003E",money_prices:[{name:"Taxi (cena za km)",value:k,date_update:c},{name:"Hlavní jídlo",value:80,date_update:c},{name:"Chleba",value:l,date_update:c},{name:"Mléko",value:12,date_update:c},{name:"Voda (500ml)",value:f,date_update:c},{name:"Espresso",value:k,date_update:c},{name:"Zmrzlina (jeden kopeček)",value:6,date_update:c},{name:"Pivo",value:18,date_update:c},{name:"Krabička cigaret",value:25,date_update:c},{name:"Coca Cola (500ml)",value:m,date_update:c}],phone_numbers_emergency:[{name:"Mezinárodní tísňová linka",value:"112",date_update:b},{name:"Policie",value:"121",date_update:b},{name:"Hasiči",value:"122",date_update:b},{name:"Zdravotnická záchranná služba",value:"123",date_update:b}],phone_prefix:"+266",coordinates:[{latitude:"-29.6099",longitude:"28.2336"}],people_religion:[{name:"Křesťanství",value:"90%"},{name:"Protestanti",value:"47,8%"},{name:"Katolíci",value:"41,8%"},{name:"Bahá'í",value:h},{name:"Muslimové",value:h},{name:"Hinduisté",value:h}],people_nationality:[{name:"Basutové",value:"99,7%"},{name:"Ostatní",value:"0,3%"}],visitors_entry:[{name:"Občanský průkaz",value:"Občanský průkaz není platným cestovním dokladem pro vstup do Lesotha. Je potřeba mít platný cestovní pas.",date_update:b},{name:"Cestovní pas",value:"Pro vstup do Lesotha je potřeba mít platný cestovní pas.",date_update:b},{name:"Vízum",value:"Pro vstup do Lesotha je většinou potřeba mít vízum. Občané Evropské unie a Švýcarska však mohou vstoupit na území Lesotha bez víza a pobýt zde maximálně 90 dnů. Pokud plánujete pobyt delší než 90 dnů, je nutné požádat o vízum před cestou na velvyslanectví Lesotha v zemi vašeho pobytu.",date_update:b},{name:"Očkování",value:"Pro vstup do Lesotha není vyžadováno žádné specifické očkování. Doporučuje se však být očkován proti běžným nemocem, jako jsou např. žloutenka A a B, tetanus, spalničky, zarděnky a příušnice.",date_update:b},{name:"Cestovní pojištění",value:"Pro vstup do Lesotha není vyžadováno mít cestovní nebo zdravotní pojištění, ale doporučuje se ho mít kvůli nepředvídatelným situacím během cesty.",date_update:b},{name:"Bezpečností situace",value:"Lesotho má poměrně vysokou kriminalitu, zejména v hlavním městě Maseru. Je třeba být opatrný a dodržovat základní bezpečnostní opatření, jako je např. nepřenášet všechny cennosti s sebou, nechodit po tmě po nebezpečných oblastech a nejezdit v noci na místech mimo města.",date_update:b},{name:"Další informace",value:"V Lesothu se používají britské zásuvky, ale také jsou běžné jihoafrické zásuvky. Měna v Lesothu je loti, ale v některých oblastech se může používat také jihoafrický rand. Je třeba si být vědom, že Lesotho je hornatá země a doprava v horách může být složitá a pomalá. Při cestování je třeba mít s sebou dostatek hotovosti, protože ne všechny oblasti mají bankomaty nebo akceptují platební karty.",date_update:b}],type_place:n,id_image_cover:i,id_image_hero:i,id_city_main:1288,affiliate:[{name:"booking",value:d}],mpz:"LS",alerts:a,zoom:[{google:l,booking:m}],ids_neighboring_countries:[{id:247}],organization:a,apps:a,links:a,information_author:a,seo_tags:a,language_phrases:a,wall_sockets:a,id:132,facts_place:a,created_at:"2023-12-27T16:33:10.517062+00:00",updated_at:"2024-02-10T00:28:20.01422+00:00",name_original:a,currency:[{code:"LSL",name:"lesothský loti"}]}],imagePlace:[{id:i,name:j,source:"\u002Fworld\u002Fstates\u002F",type:n,author:"pixabay.com",created_at:"2023-05-03T20:14:00.749527+00:00",updated_at:"2023-12-27T20:42:18.520959+00:00"}],placeContinent:[{id:f,slug:"afrika",name:"Afrika",area:30370000,population:1340000000,population_density:44.12,number_states:54,information_chatgpt:"\u003Cp\u003EAfrika je největší kontinent na Zemi a rozkládá se na ploše přesahující 30 milionů kilometrů čtverečních. Nachází se zde více než 50 zemí a žije zde více než 1,3 miliardy lidí. \u003C\u002Fp\u003E\n\u003Cp\u003EJižní Afrika, Egypt, Maroko a Keňa patří mezi nejoblíbenější turistické cíle v Africe. V Jihoafrické republice se můžete podívat na slavné Krugerův národní park a sledovat zde život zvířat v jejich přirozeném prostředí. Egypt je zase proslulý svými pyramidami, které se nacházejí v Gíze. V Maroku můžete navštívit tradiční trhy, zatímco v Keni se můžete setkat s Masajským kmenem a podívat se na úžasnou přírodu.\u003C\u002Fp\u003E\n\u003Cp\u003EAfrika má bohatou historii a kulturu. První lidé, kteří se usadili v Africe, byli loveckým a sběračským národem. Poté se v této oblasti objevily první civilizace, jako je Kúšská říše, Egyptská říše nebo Království Aksum. Afrika byla také kolonizována evropskými mocnostmi a toto období mělo značný dopad na dnešní politickou situaci na kontinentu.\u003C\u002Fp\u003E\n\u003Cp\u003EJe důležité zmínit, že Afrika má velké množství jazyků a kultur. Zahrnuje mnoho různých národů a etnických skupin, a to má vliv na různorodost obyvatelstva a kultury. Nejrozšířenějším jazykem je arabština, která se mluví především v severní Africe a v některých částech západní Afriky. Dalšími důležitými jazyky jsou svahilština, francouzština, portugalština, angličtina a mnoho dalších.\u003C\u002Fp\u003E\n\u003Cp\u003EAfrika má také nádhernou přírodu. Nachází se zde nejvyšší hora světa, Kilimandžáro, která se nachází na území Tanzanie a Keňy. Kromě toho se v Africe nachází také největší pouště na světě, Sahara, a největší prales, Kongský prales. Na tomto kontinentě můžete vidět také mnoho zvířat, jako jsou sloni, lvi, gepardi, zebry a mnoho dalších druhů. V Africe se také nachází několik nejvýznamnějších řek světa, jako je Nil, Kongo, Niger a Zambezi.\u003C\u002Fp\u003E\u003Cp\u003EAfrika je bohužel také známá pro své problémy. Mnoho zemí se potýká s chudobou, nedostatkem potravin a vody, nemocemi a válečnými konflikty. Mnoho afrických zemí závisí na zemědělství a rybolovu, což však často není dostatečně výnosné, aby zabezpečilo potřeby obyvatelstva. Kromě toho jsou některé země v Africe trvale postižené extrémními přírodními katastrofami, jako jsou sucha, povodně a bouře.\u003C\u002Fp\u003E\n\u003Cp\u003ENa druhou stranu se v Africe také nachází mnoho lidí, kteří se snaží změnit situaci a zlepšit životy svých spoluobčanů. Vznikají neziskové organizace, které se snaží pomáhat při řešení těchto problémů a zlepšovat kvalitu života v mnoha afrických zemích. Zároveň se v posledních letech objevují nové možnosti pro ekonomický růst a rozvoj, jako jsou technologické start-upy a zahraniční investice.\u003C\u002Fp\u003E\n\u003Cp\u003EAfrika je fascinující kontinent, který nabízí mnoho zážitků a zároveň v sobě ukrývá mnoho výzev. Pokud se rozhodnete navštívit Afriku, můžete se těšit na krásnou přírodu, bohatou kulturu a nezapomenutelné zážitky. Je však také důležité být obezřetný a připravený na místní podmínky, protože některé oblasti mohou být nebezpečné kvůli konfliktům nebo zločinnosti.\u003C\u002Fp\u003E",coordinates:[{latitude:1.650801,longitude:17.371642}],type_place:"continent",id_image_cover:f,id_image_hero:f,zoom:[{google:2,booking:3}],information_author:a,seo_tags:a,created_at:"2023-12-27T16:35:37.460505+00:00",updated_at:"2023-12-27T17:07:06.531847+00:00",name_original:a}]}],fetch:{},mutations:[]}}(null,"05-2023","09-2021",true,0,5,1,"\u003C1%",297,"lesotho",10,7,8,"state")));